B="BK-741"
C=[
("S22",5966,6120,"تقرير الخبير دليل يُوزن وليس حكماً يُنفَّذ","تقرر الأحكام التي يعرضها الكتاب أن المحكمة تبقى صاحبة التقدير بعد ندب الخبير، وأن تقريره نوع من الأدلة يُناقش ويُوازن مع غيره. الدرس العام: رأي المختص قيمة كبيرة لكنه ليس نهاية التفكير.","اسأل لكل تقرير: ما الذي يدعمه؟ وما الذي يعارضه؟ وكيف يتفق مع بقية الأدلة؟","القاعدة قانونية خاصة بالنظام المذكور ولا تعني أن كل رأي خبير قابل للتجاهل.","التقرير الفني يحسم القضية وحده.","16-18","conceptual","reporting",["KO-FC-04-031","KO-RS-05-004","KO-RS-06-007"],["وزن الدليل","تقرير الخبير"]),
("S22",6000,6014,"في المسائل الفنية البحتة لا يحل القاضي نفسه محل الخبير","تتكرر في الأحكام فكرة أن المسائل التقنية الصرفة تستدعي أهل الخبرة، وأن القاضي لا يستعيض عنهم برأيه الشخصي. تمييز السؤال التقني من السؤال العام يحمي من الأحكام المتسرعة.","فرّق في الملف بين سؤال يحتاج مختصاً (هل الإصابة قديمة؟) وسؤال يكفيه المنطق العام (هل تتسق الرواية؟).","التمييز بين النوعين نفسه قد يكون محل خلاف.","","16-18","conceptual","reporting",["KO-FC-04-031","KO-RS-06-004"],["مسألة فنية","حدود الاختصاص"]),
("S22",6007,6008,"الرائحة وحدها لا تكشف حقيقة مادة مضبوطة، يلزم تحليل","تذكر الأحكام أن الكشف عن حقيقة المادة المضبوطة لا يغني فيه الاعتماد على الرائحة، بل التحليل. القاعدة العملية: التعرف الحسي ظن، والتأكيد يحتاج فحصاً.","في اللعبة: 'تبدو كذا' تسجل ظناً، و'أثبت المختبر' تسجل نتيجة.","التحليل نفسه يحتاج سلسلة حيازة سليمة.","","13-15","safe","lab_limits",["KO-FC-04-019","KO-FC-04-020"],["فحص أولي","فحص تأكيدي"]),
("S22",6064,6066,"الدفع بقِدَم الإصابة أو حداثتها مسألة فنية تُحال لأهل الخبرة","يذكر الكتاب أن مدى قدم الإصابة من المسائل الفنية التي لا تستطيع المحكمة البت فيها بمفردها. وهذا يتفق مع الحذر المنهجي من تأريخ الإصابات بعمرها الظاهر.","لا تحدد عمر إصابة من لونها بنفسك؛ دوّن الوصف واطلب رأي مختص بنطاق.","تقدير عمر الجروح والكدمات من اللون غير دقيق.","الكدمة الخضراء عمرها يومان.","16-18","conceptual","timing",["KO-FC-04-021","KO-FC-04-022","KO-RS-07B-001"],["قدم الإصابة","نطاق زمني"]),
("S22",6191,6290,"المحكمة توازن بين تقارير متعارضة وتأخذ بما تطمئن إليه لأسباب معلنة","تعرض الأحكام فكرة تعدد التقارير المتعارضة: يُقارن بينها ويؤخذ بما يتسق مع الأدلة الأخرى. ما يجب أن يظل ظاهراً هو أسباب الترجيح لا ترجيح بالانطباع.","عند تعارض تقريرين اكتب جدولاً بنقاط الاتفاق والاختلاف وسبب كل اختلاف (عينة؟ منهج؟ توقيت؟).","الترجيح غير المعلل ضعيف.","","16-18","conceptual","reporting",["KO-RS-05-004","KO-RS-06-007","KO-FC-04-031"],["تقارير متعارضة","تعليل الترجيح"]),
("S22",6607,6612,"إذا تعارض الدليل القولي مع الفني وجب بيان سبب الأخذ بأحدهما","تؤكد بعض الأحكام أن التناقض بين شهادة وتقرير فني يلزم القاضي بتفسيره وبيان سبب ترجيحه. هذا يوافق منهج مقابلة الرواية بالأثر المادي.","كلما اختلف شاهد مع الأثر، اسأل أي الاحتمالات تفسر الاثنين معاً: خطأ إدراك؟ خطأ فحص؟ تلاعب؟","التناقض الظاهري قد يزول بعد تدقيق التوقيت أو الوصف.","","16-18","conceptual","witness_reliability",["KO-RS-05-014","KO-RS-06-017","KO-RS-05-008"],["دليل قولي","دليل فني"]),
("S22",6674,6680,"الاستناد إلى نتيجة تقرير دون ذكر مضمونه عيب في التسبيب","تنبه الأحكام إلى أن ذكر نتيجة تقرير دون بيان مضمونه وأسبابه لا يكفي لتسبيب الحكم. الفكرة العامة: النتيجة بلا منهجها لا تُراجَع.","اطلب من كل تقرير: ما الطريقة؟ ما العينات؟ ما حدود النتيجة؟ ثم الخلاصة.","القاعدة القانونية تخص طريقة كتابة الأحكام.","","16-18","conceptual","reporting",["KO-FC-04-031","KO-RS-05-001"],["تعليل","منهج التقرير"]),
("S22",6798,6810,"الخبير يؤدي اليمين عند توليه الوظيفة ويجوز له الاستعانة بمعاونين","تذكر الأحكام أن يمين الوظيفة يكفي عن اليمين في كل قضية، وأن الخبير قد يستعين بغيره في عمله ويتحمل مسؤولية رأيه. في المنصة: مسؤولية الرأي على من وقّعه.","اسأل: من وقّع التقرير؟ ومن شارك في العمل؟ وهل ذُكر ذلك؟","وجود معاونين غير مؤهلين يضعف الثقة.","","16-18","safe","reporting",["KO-FC-04-031","KO-FC-04-027"],["مسؤولية الخبير","معاونون"]),
("S23",7077,7160,"إجراءات الخبرة: مهمة محددة، دعوة الأطراف، تقرير موقّع ومسبّب","يعرض نص نظام الإثبات أن حكم الندب يحدد مهمة الخبير وأجل التقرير، وأن للخصوم سماع ملاحظاتهم، وأن التقرير يوقّع ويذكر الأوجه التي استند إليها بإيجاز ودقة، وأنه لا يقيد المحكمة. هذه مبادئ حوكمة الخبرة: مهمة واضحة، شفافية، تعليل.","في اللعبة: ملف الخبرة يطلب مهمة مكتوبة ومحاضر عمل وتقريراً مسبباً.","النص خاص بنظام قانوني بعينه.","","18+","safe","reporting",["KO-FC-04-031","KO-FC-04-027"],["مهمة الخبير","تقرير مسبب"]),
("S23",7100,7113,"أسباب رد الخبير: القرابة والخصومة والمصلحة والهدية والعداوة","تجيز المواد طلب رد الخبير إذا كانت له قرابة أو خصومة أو مصلحة أو تلقى هدية أو بينه وبين أحد الخصوم عداوة أو مودة ترجح عدم حياده. هذه قائمة عملية لتضارب المصالح.","كلما ظهر خبير، اسأل: هل له علاقة بأحد الأطراف تؤثر على حياده؟","وجود علاقة لا يثبت التحيز، لكنه يستوجب الإفصاح.","","16-18","safe","reporting",["KO-FC-04-027","KO-FC-04-031"],["تضارب مصالح","حياد"]),
("S23",7162,7390,"قانون تنظيم الخبرة يحدد مؤهلات الخبراء وتأديبهم وأتعابهم","تنظم المواد جداول الخبراء وشروط التعيين والمجالس التأديبية وتقدير الأتعاب. هذا نص إداري قانوني لا يفيد الفئة العمرية المستهدفة، ويُحال إلى الباحث القانوني. نكتفي بنقطة واحدة: وجود رقابة مهنية وتأديب يحمي الثقة في الخبرة.","اسأل: من يراقب جودة عمل هذا الخبير ومن يحاسبه إذا أخطأ؟","نص إداري خاص بنظام وبفترة محددة.","","18+","safe","reporting",["KO-FC-04-031"],["رقابة مهنية","تأديب"]),
]
